// 生成 project/components/bundle.css：Design System 页面编译出的 tokens.css 用的是 --<name>，
// 而 apps/web 用的是 --color-<name> / --type-<name> / --size-<name>，这里先垫一层映射，再接上 apps/web/app/globals.css 原文。
// 这样 artifact 里的预览和真实 app 用同一份样式。用法：node scripts/build-bundle.mjs
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(join(root, "project/tokens.json"), "utf8"));
const globals = readFileSync(join(root, "../../apps/web/app/globals.css"), "utf8");
const PEARL_BLOB = "/_blob/b0fd1a86db69cdfd00fc5f583db464c3"; // pearl.png 在 artifact 资产库里的地址

const shim = [
  "/* fluffdesk — bundle.css, generated by scripts/build-bundle.mjs from tokens.json + apps/web/app/globals.css; do not edit */",
  '@import url("https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600&family=Fraunces:opsz,SOFT,wght@9..144,100,400&family=Noto+Sans+SC:wght@400;500&family=Noto+Serif+SC:wght@500&display=swap");',
  ":root {",
  ...tokens.color.tokens.map((c) => `  --color-${c.name}: var(--${c.name});`),
  ...tokens.size.tokens.map((s) => `  --size-${s.name}: var(--${s.name});`),
  ...tokens.type.groups.flatMap((g) => g.styles.map((s) => `  --type-${s.name}: ${s.fontWeight} ${s.fontSize}/${s.lineHeight} var(--font-${g.family});`)),
  "}",
  "",
];
const body = globals.replace('url("/pearl.png")', `url("${PEARL_BLOB}")`);
mkdirSync(join(root, "project/components"), { recursive: true });
writeFileSync(join(root, "project/components/bundle.css"), shim.join("\n") + body);
console.log("wrote project/components/bundle.css");
